const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Lake Elton geometry
  const lakeElton = ee.Geometry.Point([45.1, 46.7]).buffer(15000);

  // 2. Acquire Landsat 5 TM data for 2004 and 2009
  const col2004 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(lakeElton)
    .filterDate('2004-01-01', '2004-12-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const col2009 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(lakeElton)
    .filterDate('2009-01-01', '2009-12-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const size2004 = col2004.size().getInfo();
  const size2009 = col2009.size().getInfo();

  if (size2004 === 0 || size2009 === 0) {
    console.log(`2004 Images: ${size2004}, 2009 Images: ${size2009}`);
    console.log('C1');
    return;
  }

  // 3. Create median composites and apply cloud mask
  const maskClouds = (img) => {
    const qa = img.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(32).eq(0).and(qa.bitwiseAnd(64).eq(0));
    return img.updateMask(cloudMask);
  };

  const img2004 = col2004.map(maskClouds).median();
  const img2009 = col2009.map(maskClouds).median();

  // 4. Select red band (SR_B3) as surface reflectance proxy
  const ref2004 = img2004.select('SR_B3');
  const ref2009 = img2009.select('SR_B3');

  // 5. Calculate mean reflectance with pixel counts
  const stats2004 = ref2004.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: lakeElton,
    scale: 3000,
    maxPixels: 1e9
  });

  const stats2009 = ref2009.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: lakeElton,
    scale: 3000,
    maxPixels: 1e9
  });

  const mean2004 = stats2004.getNumber('SR_B3_mean').getInfo();
  const count2004 = stats2004.getNumber('SR_B3_count').getInfo();
  const mean2009 = stats2009.getNumber('SR_B3_mean').getInfo();
  const count2009 = stats2009.getNumber('SR_B3_count').getInfo();

  // 6. Validation
  console.log(`2004: Mean=${(mean2004/10000).toFixed(3)}, Pixels=${Math.round(count2004)}`);
  console.log(`2009: Mean=${(mean2009/10000).toFixed(3)}, Pixels=${Math.round(count2009)}`);

  if (count2004 === 0 || count2009 === 0) {
    console.log('C2');
    return;
  }

  if (mean2004 === null || mean2009 === null || isNaN(mean2004) || isNaN(mean2009)) {
    console.log('C3');
    return;
  }

  // 7. Compare reflectance (normalized by 10000 for Landsat L2)
  const ref2004Norm = mean2004 / 10000;
  const ref2009Norm = mean2009 / 10000;

  if (ref2009Norm > ref2004Norm) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
